const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (line) => {
    const S = line.trim();
    const n = S.length;
    if (n === 0) {
        console.log('');
        rl.close();
        return;
    }

    // dp[i][atCount] = best string for prefix of length i using atCount '@' symbols.
    // atCount can be 0 or 1.
    // Initialize with null (unreachable).
    const dp = Array.from({ length: n + 1 }, () => [null, null]);
    dp[0][0] = "";

    for (let i = 0; i < n; i++) {
        for (let k = 0; k <= 1; k++) {
            const cur = dp[i][k];
            if (cur === null) continue;

            // Option 1: Take one character as a literal letter.
            if (i + 1 <= n) {
                const nextStr = cur + S[i];
                update(dp[i + 1][k], nextStr, i + 1, k);
            }

            // Option 2: Replace "at" (length 2) with '@'.
            if (k === 0 && i + 2 <= n && S.substring(i, i + 2) === "at") {
                const nextStr = cur + "@";
                update(dp[i + 2][1], nextStr, i + 2, 1);
            }

            // Option 3: Replace "dot" (length 3) with '.'.
            if (i + 3 <= n && S.substring(i, i + 3) === "dot") {
                const nextStr = cur + ".";
                update(dp[i + 3][k], nextStr, i + 3, k);
            }
        }
    }

    // Helper to compare and update dp state
    // We pass the current stored value, the candidate, and the indices for context (though not strictly needed for comparison logic here)
    function update(currentStored, candidate, nextI, nextK) {
        if (currentStored === null) {
            dp[nextI][nextK] = candidate;
            return;
        }
        if (candidate.length < currentStored.length) {
            dp[nextI][nextK] = candidate;
        } else if (candidate.length === currentStored.length && candidate < currentStored) {
            dp[nextI][nextK] = candidate;
        }
    }

    let ans = dp[n][1];

    // Validation function for a proper email address
    function isValid(email) {
        if (email === null) return false;
        // Must contain exactly one '@'
        if ((email.match(/@/g) || []).length !== 1) return false;
        // Must not start or end with '.'
        if (email[0] === '.' || email[email.length - 1] === '.') return false;
        // Must not start or end with '@'
        if (email[0] === '@' || email[email.length - 1] === '@') return false;
        // All characters must be lowercase letters, '.' or '@'
        for (const ch of email) {
            if (!((ch >= 'a' && ch <= 'z') || ch === '.' || ch === '@')) {
                return false;
            }
        }
        return true;
    }

    // According to problem statement, a solution is guaranteed to exist.
    // However, as a safeguard, if dp[n][1] is invalid (should not happen with correct logic),
    // we could search other states, but the constraints guarantee dp[n][1] is the answer.
    console.log(ans);
    rl.close();
});
